  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("작업");
  if (selectedEvidence === null) {
    return <section><p>근거를 선택해 주세요.</p>
      <button onClick={() => navigate("/select")}>근거 설정</button></section>;
  }
  return <section>
    <nav aria-label="근거 종류">{standardTabs.map(tab =>
      <button key={tab} aria-pressed={activeTab === tab} onClick={() => setActiveTab(tab)}>{tab}</button>)}</nav>
    <h2>{activeTab}</h2>
    <p>선택한 근거: {selectedEvidence}</p>
    <EvidenceKind kind={activeTab === "작업" ? "work" : "monitoring"} />
    <EvidenceSummary />
  </section>;
}

